insert into ordenes(id,obra_id,numero,fecha,titulo,motivo,lineas,impacto_plazo_dias,estado,decision_fecha,decision_comentario) values ('mtg-2026-001-os-001','mtg-2026-001','OS-001','2026-10-02','Desvío de zanja por tubería de agua','Durante el zanjado apareció una tubería de agua potable que no figura en los planos. Para no afectarla, la ruta se desvía 6 m por la acera. Se aumentan zanja y subducto en la misma longitud.','[{"tipo": "aumento", "partida_id": "p-zd-25", "cod_cliente": "ZD-25", "descripcion": "Zanjado Urbano en acera de concreto con equipo neumático. Profundidad 45 cm. Ancho 15 cm. Paquete 2 sub-ductos. Incluye relleno con concreto Rcc 210 kg/cm2. Acabado obra limpia. Horario Diurno", "unidad": "m", "cantidad": 6, "pu": 57.31, "item_ref": "1.1"}, {"tipo": "aumento", "partida_id": "p-sd-2", "cod_cliente": "SD-2", "descripcion": "Suministro, transporte e instalación de sub-ducto PEAD Tipo - SDR-11, diámetro interno 1\" en canalizaciones y escalerillas.", "unidad": "m", "cantidad": 6, "pu": 4.38, "item_ref": "2.1"}]'::jsonb,1,'aprobada','2026-10-02T16:40:00Z','Aprobado en sitio con el administrador. (dato de ejemplo)');
insert into ordenes(id,obra_id,numero,fecha,titulo,motivo,lineas,impacto_plazo_dias,estado,decision_fecha,decision_comentario) values ('mtg-2026-001-os-002','mtg-2026-001','OS-002','2026-10-06','Subida por fachada al cuarto técnico','El cuarto técnico está en el piso 2 y la canalización interna existente está ocupada. Proponemos subir por fachada con tubería metálica flexible tipo liquid-tight de 1", lo que alarga el tendido de fibra en 25 m.','[{"tipo": "nueva", "partida_id": "p-tb-18", "cod_cliente": "TB-18", "descripcion": "Suministro, transporte e instalación de tubería LIQUID-TIGHT. Dia. 1\" uso interior.", "unidad": "m", "cantidad": 10, "pu": 74.07, "wbs": "2 Canalización"}, {"tipo": "aumento", "partida_id": "p-td-1", "cod_cliente": "TD-1", "descripcion": "Tendido de cable de fibra óptica. Método halado.", "unidad": "m", "cantidad": 25, "pu": 2.48, "item_ref": "4.1"}]'::jsonb,1,'pendiente',null,null);
insert into ordenes(id,obra_id,numero,fecha,titulo,motivo,lineas,impacto_plazo_dias,estado,decision_fecha,decision_comentario) values ('mtg-2026-001-os-003','mtg-2026-001','OS-003','2026-10-06','Tornillos de seguridad en tanquillas','Dos de las tres tanquillas no tienen tapa con cierre de seguridad. Para proteger la fibra contra robo recomendamos instalar tornillos tipo McGard. Es opcional; si la rechaza, la obra sigue sin cambios.','[{"tipo": "nueva", "partida_id": "p-tq-5", "cod_cliente": "TQ-5", "descripcion": "Suministro tornillos de seguridad tipo MC Gard", "unidad": "und", "cantidad": 2, "pu": 102.24, "wbs": "3 Tanquillas"}]'::jsonb,0,'pendiente',null,null);
